    SparseMultiplyAdd(A, x, residual);

    // Solve for correction and update x.
    SparseSolve(factorization, residual, correction);

    // vDSP operation that calculates `x[i] -= correction[i]` for
    // `i` in `0 ..< n`.
    vDSP_vsubD(correction.data, 1,
               x.data, 1,
               x.data, 1,
               n)
}
